-- Schema DDL generated by Prisma migrate diff; data-preservation steps reviewed below.
BEGIN;
LOCK TABLE clients, employees, attachments, audit_logs IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM clients GROUP BY regexp_replace(document, '[^0-9]', '', 'g')
        HAVING count(DISTINCT ROW(trim("fullName"), "typeId", coalesce(email, ''), regexp_replace(coalesce(phone, ''), '[^0-9]', '', 'g'))) > 1) THEN
        RAISE EXCEPTION 'Conflicting client registration for the same CPF/CNPJ. Reconcile names, type and contacts before migrating.';
    END IF;
    IF EXISTS (SELECT 1 FROM clients GROUP BY "firmId", regexp_replace(document, '[^0-9]', '', 'g') HAVING count(*) > 1) THEN
        RAISE EXCEPTION 'Duplicate normalized client documents within one branch. Reconcile before migrating.';
    END IF;
    IF EXISTS (SELECT 1 FROM employees WHERE nullif(trim("oabNumber"), '') IS NOT NULL GROUP BY upper(trim("oabNumber"))
        HAVING count(DISTINCT trim("fullName")) > 1) THEN
        RAISE EXCEPTION 'Conflicting employee names for the same OAB. Reconcile before migrating.';
    END IF;
    IF EXISTS (SELECT 1 FROM employees WHERE nullif(trim("oabNumber"), '') IS NOT NULL GROUP BY "firmId", upper(trim("oabNumber")) HAVING count(*) > 1) THEN
        RAISE EXCEPTION 'Duplicate normalized OAB within one branch. Reconcile before migrating.';
    END IF;
END $$;
ALTER TABLE attachments DROP CONSTRAINT attachments_exactly_one_owner_check;

-- CreateTable
CREATE TABLE "client_profiles" (
    "id" SERIAL NOT NULL,
    "typeId" INTEGER NOT NULL,
    "fullName" TEXT NOT NULL,
    "document" TEXT NOT NULL,
    "email" TEXT,
    "phone" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "client_profiles_pkey" PRIMARY KEY ("id")
);
-- CreateTable
CREATE TABLE "employee_profiles" (
    "id" SERIAL NOT NULL,
    "fullName" TEXT NOT NULL,
    "oabNumber" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "employee_profiles_pkey" PRIMARY KEY ("id")
);
-- AlterTable
ALTER TABLE "audit_logs" ADD COLUMN     "clientProfileId" INTEGER,
ADD COLUMN     "employeeProfileId" INTEGER;

INSERT INTO client_profiles (id, "typeId", "fullName", document, email, phone, "createdAt", "updatedAt")
SELECT DISTINCT ON (regexp_replace(document, '[^0-9]', '', 'g')) id, "typeId", trim("fullName"),
    regexp_replace(document, '[^0-9]', '', 'g'), email, regexp_replace(phone, '[^0-9]', '', 'g'), "createdAt", "updatedAt"
FROM clients ORDER BY regexp_replace(document, '[^0-9]', '', 'g'), id;
INSERT INTO employee_profiles (id, "fullName", "oabNumber", "createdAt", "updatedAt")
SELECT DISTINCT ON (coalesce(nullif(upper(trim("oabNumber")), ''), 'no-oab:' || id)) id, trim("fullName"), nullif(upper(trim("oabNumber")), ''), "createdAt", "updatedAt"
FROM employees ORDER BY coalesce(nullif(upper(trim("oabNumber")), ''), 'no-oab:' || id), id;
SELECT setval(pg_get_serial_sequence('client_profiles','id'), coalesce((SELECT max(id) FROM client_profiles), 1), EXISTS(SELECT 1 FROM client_profiles));
SELECT setval(pg_get_serial_sequence('employee_profiles','id'), coalesce((SELECT max(id) FROM employee_profiles), 1), EXISTS(SELECT 1 FROM employee_profiles));
ALTER TABLE clients ADD COLUMN "profileId" INTEGER;
ALTER TABLE employees ADD COLUMN "profileId" INTEGER;
ALTER TABLE attachments ADD COLUMN "clientProfileId" INTEGER, ADD COLUMN "employeeProfileId" INTEGER;
UPDATE clients c SET "profileId" = p.id FROM client_profiles p WHERE regexp_replace(c.document, '[^0-9]', '', 'g') = p.document;
UPDATE employees e SET "profileId" = p.id FROM employee_profiles p
WHERE (nullif(upper(trim(e."oabNumber")), '') IS NOT NULL AND upper(trim(e."oabNumber")) = p."oabNumber")
    OR (nullif(trim(e."oabNumber"), '') IS NULL AND e.id = p.id);
UPDATE attachments a SET "clientProfileId" = c."profileId" FROM clients c WHERE a."clientId" = c.id;
UPDATE attachments a SET "employeeProfileId" = e."profileId" FROM employees e WHERE a."employeeId" = e.id;
ALTER TABLE clients ALTER COLUMN "profileId" SET NOT NULL;
ALTER TABLE employees ALTER COLUMN "profileId" SET NOT NULL;

-- DropForeignKey
ALTER TABLE "clients" DROP CONSTRAINT "clients_typeId_fkey";

