-- Preserve original mixed audit payloads locally; derive shared registration-only history.
INSERT INTO audit_logs ("firmId", "actorId", "actorName", "actorEmail", action, "entityType", "entityId", "entityName", "changeData", "ipAddress", "userAgent", description, "createdAt", "clientProfileId", "employeeProfileId")
SELECT a."firmId", a."actorId", a."actorName", a."actorEmail", a.action,
    CASE WHEN a."entityType" = 'Client' THEN 'ClientProfile' ELSE 'EmployeeProfile' END,
    coalesce(c."profileId", e."profileId")::text, a."entityName", shared.payload, a."ipAddress", a."userAgent",
    'Histórico cadastral compartilhado (origem #' || a.id || ').', a."createdAt", c."profileId", e."profileId"
FROM audit_logs a
LEFT JOIN clients c ON a."entityType" = 'Client' AND a."entityId" = c.id::text
LEFT JOIN employees e ON a."entityType" = 'Employee' AND a."entityId" = e.id::text
CROSS JOIN LATERAL (
    SELECT coalesce(jsonb_object_agg(entry.key, entry.value), '{}'::jsonb) AS payload
    FROM (
        SELECT key, value FROM jsonb_each(CASE WHEN jsonb_typeof(a."changeData"::jsonb) = 'object' THEN a."changeData"::jsonb ELSE '{}'::jsonb END)
        WHERE key IN ('fullName','document','email','phone','oabNumber')
        UNION ALL
        SELECT outer_entry.key, (SELECT coalesce(jsonb_object_agg(inner_entry.key, inner_entry.value), '{}'::jsonb)
            FROM jsonb_each(CASE WHEN jsonb_typeof(outer_entry.value) = 'object' THEN outer_entry.value ELSE '{}'::jsonb END) inner_entry WHERE inner_entry.key IN ('fullName','document','email','phone','oabNumber'))
        FROM jsonb_each(CASE WHEN jsonb_typeof(a."changeData"::jsonb) = 'object' THEN a."changeData"::jsonb ELSE '{}'::jsonb END) outer_entry WHERE outer_entry.key IN ('before','after') AND jsonb_typeof(outer_entry.value) = 'object'
    ) entry
) shared
WHERE (c.id IS NOT NULL OR e.id IS NOT NULL) AND a.action IN ('CREATE','UPDATE') AND shared.payload <> '{}'::jsonb;
UPDATE audit_logs l SET "clientProfileId" = a."clientProfileId", "employeeProfileId" = a."employeeProfileId"
FROM attachments a WHERE l."entityType" = 'Attachment' AND l."entityId" = a.id::text
    AND (a."clientProfileId" IS NOT NULL OR a."employeeProfileId" IS NOT NULL);
-- Deleted attachment rows still have retained owners in their before payload.
UPDATE audit_logs l SET "clientProfileId" = c."profileId" FROM clients c
WHERE l."entityType" = 'Attachment' AND l."clientProfileId" IS NULL AND l."changeData"::jsonb #>> '{before,clientId}' = c.id::text;
UPDATE audit_logs l SET "employeeProfileId" = e."profileId" FROM employees e
WHERE l."entityType" = 'Attachment' AND l."employeeProfileId" IS NULL AND l."changeData"::jsonb #>> '{before,employeeId}' = e.id::text;
ALTER TABLE clients DROP COLUMN document, DROP COLUMN email, DROP COLUMN "fullName", DROP COLUMN phone, DROP COLUMN "typeId";
ALTER TABLE employees DROP COLUMN "fullName", DROP COLUMN "oabNumber";
ALTER TABLE attachments DROP COLUMN "clientId", DROP COLUMN "employeeId";
ALTER TABLE attachments ADD CONSTRAINT attachments_exactly_one_owner_check CHECK (
    num_nonnulls("clientProfileId", "employeeProfileId", "contractId", "expenseId", "feeId", "remunerationId") = 1
);





















